export const TrustpilotStars: React.FC<{ rating?: 4.6 | 4.8 | 5; size?: number }> = ({
  rating = 5,
  size = 18,
}) => {
  const fifth = rating === 4.6 ? 60 : rating === 4.8 ? 80 : 100;
  const percentages = [100, 100, 100, 100, fifth];
  return (
    <ul className="trustpilot-stars-list" aria-label={`${rating} out of 5 stars`}>
      {percentages.map((pct, idx) => (
        <li key={idx}>
          <div
            className="trustpilot-star-box"
            style={{
              width: size,
              height: size,
              backgroundImage: `linear-gradient(to right, #C98B1B 0% ${pct}%, #E5DEC9 ${pct}% 100%)`,
            }}
          >
            <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 46 46">
              <path
                fill="#FFF"
                d="M39.534 19.711L13.23 38.801l3.838-11.798L7.021 19.71h12.42l3.837-11.798 3.837 11.798h12.419zm-16.255 11.8L30.462 30l2.862 8.8-10.045-7.29z"
              />
            </svg>
          </div>
        </li>
      ))}
    </ul>
  );
};

